_sciebo_commands='setup doctor discover list check sync verify status pause resume folders mount umount mounts cleanup schedule trash versions share notifications activity presence lock unlock locks quota open conflicts retry account logout config support nextcloudcmd watch limit unlimited network filters file search recent comments favorites tags server hydrate provision logs edit ignored announcements preview download update help'
_sciebo_dispatch_commands='folders schedule trash share presence account config filters file tags server logs'
_sciebo_global_opts='-h --help --profile --trust --non-interactive --debug --log-file --confdir --log-dir --log-expire --version -V'

_sciebo_compgen() {
  local cur="$1"
  shift
  # shellcheck disable=SC2207  # word-splitting the completion list is intended
  COMPREPLY=($(compgen -W "$*" -- "$cur"))
}

_sciebo_filedir() {
  local cur="$1"
  if declare -F _filedir >/dev/null 2>&1; then
    _filedir
  else
    # shellcheck disable=SC2207  # word-splitting the file list is intended
    COMPREPLY=($(compgen -f -- "$cur"))
  fi
}

_sciebo_dirs() {
  local cur="$1"
  if declare -F _filedir >/dev/null 2>&1; then
    _filedir -d
  else
    # shellcheck disable=SC2207  # word-splitting the directory list is intended
    COMPREPLY=($(compgen -d -- "$cur"))
  fi
}

_sciebo_project_root() {
  local src="${BASH_SOURCE[0]}" dir
  case "$src" in
    */*) ;;
    *) src="./$src" ;;
  esac
  dir="$(cd "${src%/*}" 2>/dev/null && pwd)" || return 0
  dir="${dir%/*}"
  [[ -n "$dir" ]] || dir="/"
  [[ -d "${dir}/config" ]] && printf '%s' "$dir"
}

_sciebo_profile_names() {
  local root name base
  root="$(_sciebo_project_root)"
  if [[ -n "$root" && -d "${root}/config/profiles" ]]; then
    for name in "${root}/config/profiles"/*/; do
      [[ -d "$name" ]] || continue
      base="${name%/}"
      printf '%s\n' "${base##*/}"
    done
  fi
  printf 'default\n'
}

_sciebo_profiles() {
  local cur="$1" names
  names="$(_sciebo_profile_names)"
  _sciebo_compgen "$cur" "$names"
}

_sciebo_is_dispatch() {
  case " $_sciebo_dispatch_commands " in
    *" $1 "*) return 0 ;;
  esac
  return 1
}

# _sciebo_complete_action ACTION CUR - dispatch a value/positional ACTION
# (none/files/dirs/profiles/commands/enum:a,b,c) against CUR.
_sciebo_complete_action() {
  local action="$1" cur="$2" list
  case "$action" in
    files) _sciebo_filedir "$cur" ;;
    dirs) _sciebo_dirs "$cur" ;;
    profiles) _sciebo_profiles "$cur" ;;
    commands) _sciebo_compgen "$cur" "$_sciebo_commands" ;;
    enum:*)
      list="${action#enum:}"
      _sciebo_compgen "$cur" "${list//,/ }"
      ;;
    *) COMPREPLY=() ;;
  esac
}

