    'share:list:0') _SCIEBO_POS_ACTION=none ;;
    'share:info:0') _SCIEBO_POS_ACTION=none ;;
    'share:update:0') _SCIEBO_POS_ACTION=none ;;
    'share:remove:0') _SCIEBO_POS_ACTION=none ;;
    'share:leave:0') _SCIEBO_POS_ACTION=none ;;
    'share:accept:0') _SCIEBO_POS_ACTION=none ;;
    'share:decline:0') _SCIEBO_POS_ACTION=none ;;
    'share:send-email:0') _SCIEBO_POS_ACTION=none ;;
    'share:search:0') _SCIEBO_POS_ACTION=none ;;
    'share:copy-internal:0') _SCIEBO_POS_ACTION=none ;;
    'presence:set:0') _SCIEBO_POS_ACTION=enum:online,away,dnd,offline ;;
    'lock:-:0') _SCIEBO_POS_ACTION=none ;;
    'unlock:-:0') _SCIEBO_POS_ACTION=none ;;
    'open:-:0') _SCIEBO_POS_ACTION=files ;;
    'retry:-:0') _SCIEBO_POS_ACTION=none ;;
    'retry:-:1') _SCIEBO_POS_ACTION=none ;;
    'account:add:0') _SCIEBO_POS_ACTION=none ;;
    'account:remove:0') _SCIEBO_POS_ACTION=profiles ;;
    'account:use:0') _SCIEBO_POS_ACTION=profiles ;;
    'config:get:0') _SCIEBO_POS_ACTION=none ;;
    'nextcloudcmd:-:0') _SCIEBO_POS_ACTION=dirs ;;
    'nextcloudcmd:-:1') _SCIEBO_POS_ACTION=none ;;
    'filters:show:0') _SCIEBO_POS_ACTION=none ;;
    'file:info:0') _SCIEBO_POS_ACTION=none ;;
    'file:activity:0') _SCIEBO_POS_ACTION=none ;;
    'file:shares:0') _SCIEBO_POS_ACTION=none ;;
    'search:-:0') _SCIEBO_POS_ACTION=none ;;
    'comments:-:0') _SCIEBO_POS_ACTION=none ;;
    'comments:-:1') _SCIEBO_POS_ACTION=enum:list,add,delete ;;
    'comments:-:2') _SCIEBO_POS_ACTION=none ;;
    'favorites:-:0') _SCIEBO_POS_ACTION=enum:list,add,remove ;;
    'favorites:-:1') _SCIEBO_POS_ACTION=none ;;
    'tags:create:0') _SCIEBO_POS_ACTION=none ;;
    'tags:assign:0') _SCIEBO_POS_ACTION=none ;;
    'tags:assign:1') _SCIEBO_POS_ACTION=none ;;
    'tags:clear:0') _SCIEBO_POS_ACTION=none ;;
    'hydrate:-:0') _SCIEBO_POS_ACTION=none ;;
    'logs:show:0') _SCIEBO_POS_ACTION=none ;;
    'logs:tail:0') _SCIEBO_POS_ACTION=none ;;
    'logs:path:0') _SCIEBO_POS_ACTION=none ;;
    'edit:-:0') _SCIEBO_POS_ACTION=none ;;
    'ignored:-:0') _SCIEBO_POS_ACTION=none ;;
    'preview:-:0') _SCIEBO_POS_ACTION=none ;;
    'download:-:0') _SCIEBO_POS_ACTION=none ;;
    'download:-:1') _SCIEBO_POS_ACTION=none ;;
    'help:-:0') _SCIEBO_POS_ACTION=commands ;;
  esac
  if [ -z "$_SCIEBO_POS_ACTION" ]; then
    case "$cmd:$sub" in
    'trash:restore') _SCIEBO_POS_ACTION=none ;;    'trash:rm') _SCIEBO_POS_ACTION=none ;;    esac
  fi
}

_sciebo() {
  local cur cmd='' sub='-' w i pos=0 pending_flag='' is_dispatch=0 seen_sub=0
  COMPREPLY=()
  cur="${COMP_WORDS[COMP_CWORD]}"

  # --help/-h before the cursor ends completion.
  for ((i = 1; i < COMP_CWORD; i++)); do
    case "${COMP_WORDS[i]}" in
      -h | --help) return 0 ;;
    esac
  done

  for ((i = 1; i < COMP_CWORD; i++)); do
    w="${COMP_WORDS[i]}"
    if [[ -n "$pending_flag" ]]; then
      pending_flag=''
      continue
    fi
    case "$w" in
      --*=*) continue ;;
      -*)
        _sciebo_opt_lookup "${cmd:--}" "$sub" "$w"
        case "$_SCIEBO_OPT_KIND" in
          value | optional-value | repeatable | two-arg) pending_flag="$w" ;;
        esac
        continue
        ;;
    esac
    if [[ -z "$cmd" ]]; then
      cmd="$w"
      if _sciebo_is_dispatch "$cmd"; then is_dispatch=1; else is_dispatch=0; fi
    elif [[ "$is_dispatch" -eq 1 && "$seen_sub" -eq 0 ]]; then
      sub="$w"
      seen_sub=1
    else
      pos=$((pos + 1))
    fi
  done

  # A "--flag=partial" at the cursor completes that flag's value inline,
  # for every valued option (not just a hardcoded pair).
  case "$cur" in
    --*=*)
      local flagname="${cur%%=*}" partial="${cur#*=}"
      _sciebo_opt_lookup "${cmd:--}" "$sub" "$flagname"
      case "$_SCIEBO_OPT_KIND" in
        value | optional-value | repeatable | two-arg)
          _sciebo_complete_action "$_SCIEBO_OPT_ACTION" "$partial"
          local j
          for j in "${!COMPREPLY[@]}"; do
            COMPREPLY[j]="${flagname}=${COMPREPLY[j]}"
          done
          ;;
      esac
      return 0
      ;;
  esac

  if [[ -n "$pending_flag" ]]; then
    _sciebo_opt_lookup "${cmd:--}" "$sub" "$pending_flag"
    # An optional-value option whose next word looks like a flag is not
    # given a value by the real parser (it falls back to its default and
    # the word is a fresh option instead); every other kind always
    # consumes the next word, matching opt_parse.
    if [[ "$_SCIEBO_OPT_KIND" != optional-value || "$cur" != -* ]]; then
      _sciebo_complete_action "$_SCIEBO_OPT_ACTION" "$cur"
      return 0
    fi
  fi

  if [[ -z "$cmd" ]]; then
    _sciebo_compgen "$cur" "$_sciebo_commands $_sciebo_global_opts"
    return 0
  fi

  if [[ "$cur" == -* ]]; then
    _sciebo_compgen "$cur" "$(_sciebo_options_for "$cmd" "$sub") $_sciebo_global_opts"
    return 0
  fi

  if [[ "$is_dispatch" -eq 1 && "$seen_sub" -eq 0 ]]; then
    _sciebo_compgen "$cur" "$(_sciebo_subs_for "$cmd")"
    return 0
  fi

  _sciebo_pos_action "$cmd" "$sub" "$pos"
  _sciebo_complete_action "$_SCIEBO_POS_ACTION" "$cur"
}

complete -F _sciebo sciebo
